from pydantic.dataclasses import dataclass

@dataclass
class APIKeyRecord:
    id: int
    name: str
    masked_key: str
    owner_id: int

@router.get("/developers/keys/{key_id}", response_model=APIKeyRecord)
async def get_api_key_details(
    key_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    key = db.query(APIKey).filter(
        APIKey.id == key_id,
        APIKey.owner_id == current_user.id
    ).first()
    if not key:
        raise HTTPException(status_code=404, detail="API key not found or access denied")
    return APIKeyRecord(
        id=key.id,
        name=key.name,
        masked_key=f"...{key.raw_plaintext_secret[-4:]}",
        owner_id=key.owner_id
    )
